from collections import Counter

sums = []
for x in range(10):
    for y in range(10):
        for z in range(10):
            # R = |x+y-0-0| + |y+z-0-0| + |z+x-0-0|
            # Since x, y, z >= 0, R = (x+y) + (y+z) + (z+x) = 2(x+y+z)
            # We check the sum S = x+y+z, as R is uniquely determined by S.
            S = x + y + z
            sums.append(S)

# Count the frequency of each sum S
sum_counts = Counter(sums)

# Check if any sum appears more than once (meaning multiple triplets map to the same R)
duplicates_exist = False
print("Sum counts (S = x+y+z):")
for s, count in sum_counts.items():
    print(f"S={s}: Count={count}")
    if count > 1:
        duplicates_exist = True

if duplicates_exist:
    print("\nResult: Yes, distinct triplets yield the same value R.")
else:
    print("\nResult: No, all triplets yield distinct values R.")

